CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_privacy_insert AFTER INSERT ON ik_d1_staging_index BEGIN DELETE FROM ik_d1_staging_headers WHERE stage_id=NEW.stage_id; END;

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_privacy_update AFTER UPDATE ON ik_d1_staging_index BEGIN DELETE FROM ik_d1_staging_headers WHERE stage_id=OLD.stage_id OR stage_id=NEW.stage_id; END;

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_privacy_delete AFTER DELETE ON ik_d1_staging_index BEGIN DELETE FROM ik_d1_staging_headers WHERE stage_id=OLD.stage_id; END;

CREATE TABLE IF NOT EXISTS ik_d1_preparation_steps (id TEXT PRIMARY KEY, destination TEXT NOT NULL, namespace TEXT NOT NULL, mapping_version TEXT NOT NULL, principal_id TEXT NOT NULL, operation_key TEXT NOT NULL, reversal_policy TEXT NOT NULL, codec_id TEXT, source_digest TEXT NOT NULL, total INTEGER NOT NULL, records INTEGER NOT NULL DEFAULT 0, stages TEXT NOT NULL DEFAULT '[]', phase TEXT NOT NULL CHECK(phase IN ('collecting','hashing','combining','prepared')), hash_json TEXT, fingerprint TEXT, verified_revision INTEGER, revision INTEGER NOT NULL DEFAULT 0, UNIQUE(destination,principal_id,operation_key));

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_binding BEFORE UPDATE OF id,destination,namespace,mapping_version,principal_id,operation_key,reversal_policy,codec_id,source_digest,total ON ik_d1_preparation_steps BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_BINDING_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_revision BEFORE UPDATE ON ik_d1_preparation_steps WHEN NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_CHANGED'); END;

CREATE TABLE IF NOT EXISTS ik_d1_stream_sources (stream_id TEXT PRIMARY KEY REFERENCES ik_d1_streams(id) ON DELETE CASCADE, destination TEXT NOT NULL, source_digest TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS ik_d1_retirements (id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('job','stream')), destination TEXT NOT NULL, receipt_id TEXT NOT NULL, retired_at TEXT NOT NULL, PRIMARY KEY(id, kind));

CREATE TABLE IF NOT EXISTS ik_d1_erasure_journal (id TEXT PRIMARY KEY, destination TEXT NOT NULL, recorded_at TEXT NOT NULL, records_erased INTEGER NOT NULL CHECK(records_erased>=0), jobs_retired INTEGER NOT NULL CHECK(jobs_retired>=0), streams_retired INTEGER NOT NULL CHECK(streams_retired>=0), stores_json TEXT NOT NULL CHECK(json_valid(stores_json)));

CREATE INDEX IF NOT EXISTS ik_d1_erasure_journal_time ON ik_d1_erasure_journal(destination, recorded_at);

CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_insert BEFORE INSERT ON ik_d1_erasure_journal WHEN EXISTS(SELECT 1 FROM ik_d1_erasure_journal WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_insert BEFORE INSERT ON ik_d1_retirements WHEN EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=NEW.id AND kind=NEW.kind) BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_update BEFORE UPDATE ON ik_d1_erasure_journal BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_delete BEFORE DELETE ON ik_d1_erasure_journal BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_update BEFORE UPDATE ON ik_d1_retirements BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_delete BEFORE DELETE ON ik_d1_retirements BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;

CREATE TABLE IF NOT EXISTS ik_d1_erasure_tally (receipt_id TEXT NOT NULL, store TEXT NOT NULL, image TEXT NOT NULL);

DROP TRIGGER IF EXISTS ik_d1_stream_revision_update;

CREATE TRIGGER ik_d1_stream_revision_update BEFORE UPDATE ON ik_d1_stream_revisions WHEN NEW.stream_id IS NOT OLD.stream_id OR NEW.destination IS NOT OLD.destination OR NEW.mapping_version IS NOT OLD.mapping_version OR NEW.principal_id IS NOT OLD.principal_id OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.total IS NOT OLD.total OR NEW.layout_hash IS NOT OLD.layout_hash OR NEW.layout_revision<OLD.layout_revision OR NEW.progress_revision<=OLD.progress_revision OR ((NEW.namespace IS NOT OLD.namespace OR NEW.operation_key IS NOT OLD.operation_key) AND NOT (NEW.namespace='' AND NEW.operation_key='' AND NOT EXISTS(SELECT 1 FROM ik_d1_streams WHERE id=OLD.stream_id) AND EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=OLD.stream_id AND kind='stream'))) BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_REVISION_CHANGED'); END;

CREATE TABLE IF NOT EXISTS ik_d1_erasure_progress (id TEXT PRIMARY KEY,destination TEXT NOT NULL,request_hash TEXT NOT NULL,generation TEXT NOT NULL,phase TEXT NOT NULL CHECK(phase IN ('index','values','sealed','complete')),index_rows INTEGER NOT NULL CHECK(index_rows>=0),value_rows INTEGER NOT NULL CHECK(value_rows>=0),revision INTEGER NOT NULL CHECK(revision=index_rows+value_rows),records_erased INTEGER NOT NULL CHECK(records_erased>=0),field_matches_json TEXT NOT NULL CHECK(json_valid(field_matches_json)),created_at TEXT NOT NULL);

CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_progress_insert BEFORE INSERT ON ik_d1_erasure_progress WHEN EXISTS(SELECT 1 FROM ik_d1_erasure_progress WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_OPERATION_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_progress_binding BEFORE UPDATE ON ik_d1_erasure_progress WHEN NEW.id IS NOT OLD.id OR NEW.destination IS NOT OLD.destination OR NEW.request_hash IS NOT OLD.request_hash OR NEW.created_at IS NOT OLD.created_at OR OLD.phase='complete' BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_OPERATION_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_progress_delete BEFORE DELETE ON ik_d1_erasure_progress WHEN OLD.phase='complete' BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_OPERATION_CHANGED'); END;

-- Balm's schedule: treatment rooms, recurring series, and a waitlist whose
-- entries are offered freed slots by email (the first to accept is booked).
CREATE TABLE bm_rooms (
 id TEXT PRIMARY KEY, name TEXT NOT NULL,
 active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), version INTEGER NOT NULL DEFAULT 1
);

-- One booking request for many visits; skipped dates were chosen by a person, never dropped by Balm.
CREATE TABLE bm_series (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id),
 practitioner_id TEXT NOT NULL REFERENCES bm_staff(id), service_id TEXT NOT NULL REFERENCES bm_services(id),
 room_id TEXT REFERENCES bm_rooms(id), pattern TEXT NOT NULL CHECK(json_valid(pattern)),
 skipped TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(skipped)), created_at TEXT NOT NULL, created_by TEXT NOT NULL
);

ALTER TABLE bm_appointments ADD COLUMN room_id TEXT REFERENCES bm_rooms(id);
ALTER TABLE bm_appointments ADD COLUMN series_id TEXT REFERENCES bm_series(id);
ALTER TABLE bm_appointments ADD COLUMN offer_id TEXT;
CREATE INDEX bm_appointments_room ON bm_appointments(room_id,start_at);
CREATE INDEX bm_appointments_series ON bm_appointments(series_id,start_at);
CREATE INDEX bm_appointments_start ON bm_appointments(start_at);

CREATE TABLE bm_waitlist (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id),
 practitioner_id TEXT REFERENCES bm_staff(id), service_id TEXT NOT NULL REFERENCES bm_services(id),
 earliest_date TEXT NOT NULL, latest_date TEXT NOT NULL, note TEXT NOT NULL DEFAULT '',
 status TEXT NOT NULL CHECK(status IN ('waiting','booked','removed')),
 appointment_id TEXT REFERENCES bm_appointments(id), created_at TEXT NOT NULL, created_by TEXT NOT NULL,
 version INTEGER NOT NULL DEFAULT 1, CHECK(earliest_date<=latest_date)
);
CREATE INDEX bm_waitlist_status ON bm_waitlist(status,practitioner_id);

-- A freed slot offered to every matching entry at once.
CREATE TABLE bm_offers (
 id TEXT PRIMARY KEY, source_appointment_id TEXT NOT NULL REFERENCES bm_appointments(id),
 practitioner_id TEXT NOT NULL REFERENCES bm_staff(id), room_id TEXT REFERENCES bm_rooms(id),
 start_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('open','taken','closed')),
 created_at TEXT NOT NULL, appointment_id TEXT REFERENCES bm_appointments(id), closed_at TEXT
);
CREATE TABLE bm_offer_recipients (
 offer_id TEXT NOT NULL REFERENCES bm_offers(id), entry_id TEXT NOT NULL REFERENCES bm_waitlist(id),
 offer_token_hash TEXT NOT NULL UNIQUE, channel TEXT NOT NULL DEFAULT 'email' CHECK(channel IN ('email','text')),
 delivery TEXT NOT NULL DEFAULT 'pending', outcome TEXT CHECK(outcome IN ('accepted','too_late')),
 responded_at TEXT, taken_notice TEXT, PRIMARY KEY(offer_id,entry_id)
);

-- Balm patient payments through the clinic's own Stripe account: cards saved
-- with the patient's consent, copays charged at check-in, pay links for any
-- balance, and the codes a superbill needs. Card numbers never reach Balm.
ALTER TABLE bm_staff ADD COLUMN npi TEXT NOT NULL DEFAULT '';
ALTER TABLE bm_clients ADD COLUMN copay_cents INTEGER CHECK(copay_cents IS NULL OR copay_cents BETWEEN 0 AND 1000000);
ALTER TABLE bm_appointments ADD COLUMN checked_in_at TEXT;
ALTER TABLE bm_appointments ADD COLUMN checked_in_by TEXT;

-- The visit's billing codes: CPT lines with units and modifiers, ICD-10 diagnoses in order.
CREATE TABLE bm_visit_codes (
 appointment_id TEXT NOT NULL REFERENCES bm_appointments(id), kind TEXT NOT NULL CHECK(kind IN ('cpt','icd10')),
 position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 12), code TEXT NOT NULL,
 modifiers TEXT NOT NULL DEFAULT '', units INTEGER CHECK(units IS NULL OR units BETWEEN 1 AND 99),
 saved_by TEXT NOT NULL, saved_at TEXT NOT NULL, PRIMARY KEY(appointment_id,kind,position)
);

-- The clinic's Stripe connection; the key and webhook secret are sealed with the session secret.
CREATE TABLE bm_stripe (
 id INTEGER PRIMARY KEY CHECK(id=1), key_sealed TEXT NOT NULL, key_hint TEXT NOT NULL, livemode INTEGER NOT NULL CHECK(livemode IN (0,1)),
 account_id TEXT NOT NULL, account_name TEXT NOT NULL, country TEXT NOT NULL,
 webhook_id TEXT, webhook_secret_sealed TEXT, connected_by TEXT NOT NULL, connected_at TEXT NOT NULL
);
CREATE TABLE bm_stripe_customers (
 client_id TEXT NOT NULL REFERENCES bm_clients(id), account_id TEXT NOT NULL, customer_id TEXT NOT NULL,
 created_at TEXT NOT NULL, PRIMARY KEY(client_id,account_id)
);

-- One live card on file per patient, kept with the exact consent the patient gave.
CREATE TABLE bm_cards (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id), account_id TEXT NOT NULL,
 customer_id TEXT NOT NULL, setup_intent TEXT NOT NULL UNIQUE,
 brand TEXT NOT NULL, last4 TEXT NOT NULL, exp_month INTEGER NOT NULL, exp_year INTEGER NOT NULL,
 consent_text TEXT NOT NULL, consent_sha256 TEXT NOT NULL, consented_at TEXT NOT NULL,
 saved_at TEXT NOT NULL, removed_at TEXT, removed_by TEXT
);
CREATE UNIQUE INDEX bm_cards_live ON bm_cards(client_id) WHERE removed_at IS NULL;

-- A patient's private link: statement, pay any balance, save a card. Stored only as a hash.
-- Links are bearer credentials and stay out of archives, so link_id below is not a foreign key.
CREATE TABLE bm_pay_links (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, client_id TEXT NOT NULL REFERENCES bm_clients(id),
 purpose TEXT NOT NULL CHECK(purpose IN ('balance','card')), created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 expires_at TEXT NOT NULL, delivery TEXT NOT NULL CHECK(delivery IN ('email','text','shown')),
 delivery_result TEXT NOT NULL DEFAULT '', opened_at TEXT
);
CREATE INDEX bm_pay_links_client ON bm_pay_links(client_id,created_at);

-- A card form the patient opened from a link, after ticking the consent shown to them.
CREATE TABLE bm_card_setups (
 id TEXT PRIMARY KEY, link_id TEXT NOT NULL, client_id TEXT NOT NULL REFERENCES bm_clients(id),
 consent_text TEXT NOT NULL, consented_at TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('open','saved','expired')), card_id TEXT, created_at TEXT NOT NULL
);

-- Money taken through Stripe. applied_cents is the part posted to invoices as bm_payments
-- rows; the rest is the patient's credit, applied when the next invoice is approved.
CREATE TABLE bm_card_payments (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id),
 kind TEXT NOT NULL CHECK(kind IN ('copay','charge','link')),
 appointment_id TEXT REFERENCES bm_appointments(id), invoice_id TEXT REFERENCES bm_invoices(id), link_id TEXT,
 amount_cents INTEGER NOT NULL CHECK(amount_cents BETWEEN 50 AND 10000000), applied_cents INTEGER NOT NULL DEFAULT 0,
 status TEXT NOT NULL CHECK(status IN ('open','processing','requires_action','succeeded','failed','expired')),
 checkout_session TEXT UNIQUE, payment_intent TEXT UNIQUE, card_brand TEXT, card_last4 TEXT, failure TEXT,
 receipt_number INTEGER UNIQUE, receipt_delivery TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL, created_at TEXT NOT NULL, succeeded_at TEXT, updated_at TEXT NOT NULL,
 CHECK(applied_cents BETWEEN 0 AND amount_cents)
);
CREATE INDEX bm_card_payments_client ON bm_card_payments(client_id,created_at);
ALTER TABLE bm_payments ADD COLUMN card_payment_id TEXT REFERENCES bm_card_payments(id);

-- Every Stripe event Balm accepted, once.
CREATE TABLE bm_stripe_events (id TEXT PRIMARY KEY, type TEXT NOT NULL, received_at TEXT NOT NULL);

-- Balm charting: discipline templates, signed notes locked against change,
-- addenda, CPT minutes per note, plans of care certified by the referring
-- physician through a one-use link, and the install's own scribe model key.
ALTER TABLE bm_staff ADD COLUMN credentials TEXT NOT NULL DEFAULT '';
ALTER TABLE bm_services ADD COLUMN note_template TEXT NOT NULL DEFAULT '';

ALTER TABLE bm_notes ADD COLUMN template TEXT NOT NULL DEFAULT '';
ALTER TABLE bm_notes ADD COLUMN signed_at TEXT;
ALTER TABLE bm_notes ADD COLUMN signed_revision INTEGER;
ALTER TABLE bm_notes ADD COLUMN signer_name TEXT;
ALTER TABLE bm_notes ADD COLUMN signer_credentials TEXT;
ALTER TABLE bm_notes ADD COLUMN signed_sha256 TEXT;
ALTER TABLE bm_note_revisions ADD COLUMN sections TEXT CHECK(sections IS NULL OR json_valid(sections));
ALTER TABLE bm_note_revisions ADD COLUMN charges TEXT CHECK(charges IS NULL OR json_valid(charges));
ALTER TABLE bm_note_revisions ADD COLUMN drafted_by TEXT NOT NULL DEFAULT 'author' CHECK(drafted_by IN ('author','scribe'));

-- A signed note is locked: no new revision, no rewrite, and its signature never changes.
CREATE TRIGGER bm_note_locked_revision BEFORE INSERT ON bm_note_revisions
 WHEN (SELECT signed_at FROM bm_notes WHERE id=NEW.note_id) IS NOT NULL BEGIN SELECT RAISE(ABORT,'note_locked'); END;
CREATE TRIGGER bm_note_revision_fixed BEFORE UPDATE ON bm_note_revisions BEGIN SELECT RAISE(ABORT,'note_locked'); END;
CREATE TRIGGER bm_note_signature_fixed BEFORE UPDATE ON bm_notes WHEN OLD.signed_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'note_locked'); END;

-- Changes after signing are addenda, each signed by its author when written.
CREATE TABLE bm_note_addenda (
 id TEXT PRIMARY KEY, note_id TEXT NOT NULL REFERENCES bm_notes(id), author_id TEXT NOT NULL REFERENCES bm_staff(id),
 body TEXT NOT NULL, written_at TEXT NOT NULL, signer_name TEXT NOT NULL, signer_credentials TEXT NOT NULL, sha256 TEXT NOT NULL
);
CREATE INDEX bm_note_addenda_note ON bm_note_addenda(note_id,written_at);
CREATE TRIGGER bm_note_addenda_fixed BEFORE UPDATE ON bm_note_addenda BEGIN SELECT RAISE(ABORT,'note_locked'); END;
CREATE TRIGGER bm_note_addenda_kept BEFORE DELETE ON bm_note_addenda BEGIN SELECT RAISE(ABORT,'note_locked'); END;

-- A plan of care is signed by its therapist when sent; its content never changes.
-- The referring physician certifies it once through a link stored only as a hash.
CREATE TABLE bm_plans_of_care (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id), author_id TEXT NOT NULL REFERENCES bm_staff(id),
 note_id TEXT REFERENCES bm_notes(id), content TEXT NOT NULL CHECK(json_valid(content)), content_sha256 TEXT NOT NULL,
 therapist_name TEXT NOT NULL, therapist_credentials TEXT NOT NULL, created_at TEXT NOT NULL,
 physician_name TEXT NOT NULL, physician_email TEXT NOT NULL,
 sign_token_hash TEXT UNIQUE, sign_token_expires_at TEXT, sent_at TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('sent','certified')),
 certified_at TEXT, certifier_name TEXT, certifier_credentials TEXT, certifier_npi TEXT,
 version INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX bm_plans_client ON bm_plans_of_care(client_id,created_at);
CREATE TRIGGER bm_plan_content_fixed BEFORE UPDATE ON bm_plans_of_care
 WHEN NEW.content IS NOT OLD.content OR NEW.content_sha256 IS NOT OLD.content_sha256 OR OLD.status='certified' BEGIN SELECT RAISE(ABORT,'plan_locked'); END;

-- The scribe's model: the owner's own key, sealed with the install's session secret.
CREATE TABLE bm_scribe (
 id INTEGER PRIMARY KEY CHECK(id=1), provider TEXT NOT NULL CHECK(provider IN ('anthropic','openai')),
 endpoint TEXT NOT NULL, model TEXT NOT NULL, workspace TEXT NOT NULL DEFAULT '', key_sealed TEXT NOT NULL, key_hint TEXT NOT NULL,
 updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);

-- Balm: the clinic's time zone is chosen by the owner, not assumed. Until the
-- owner saves it, the Clinic page fills it from the browser's own time zone.
-- Installs whose settings were already saved keep their zone as chosen.
ALTER TABLE bm_settings ADD COLUMN time_zone_chosen INTEGER NOT NULL DEFAULT 0 CHECK(time_zone_chosen IN (0,1));
UPDATE bm_settings SET time_zone_chosen=1 WHERE version>1 OR EXISTS(SELECT 1 FROM bm_appointments);

-- Balm: the scribe is Ready only after its test passes. Saving settings runs the
-- test; the last result is kept here. Saved keys start untested.
ALTER TABLE bm_scribe ADD COLUMN checked_at TEXT;
ALTER TABLE bm_scribe ADD COLUMN check_ok INTEGER NOT NULL DEFAULT 0 CHECK(check_ok IN (0,1));
ALTER TABLE bm_scribe ADD COLUMN check_message TEXT NOT NULL DEFAULT '';

ALTER TABLE bm_settings ADD COLUMN reminder_leads TEXT NOT NULL DEFAULT '[1440]';
ALTER TABLE bm_settings ADD COLUMN reminder_sms INTEGER NOT NULL DEFAULT 0 CHECK(reminder_sms IN (0,1));
ALTER TABLE bm_clients ADD COLUMN sms_reminder_consent INTEGER NOT NULL DEFAULT 0 CHECK(sms_reminder_consent IN (0,1));
ALTER TABLE bm_appointments ADD COLUMN patient_response TEXT NOT NULL DEFAULT 'awaiting' CHECK(patient_response IN ('awaiting','confirmed','change_requested'));
ALTER TABLE bm_appointments ADD COLUMN patient_response_at TEXT;
CREATE TABLE bm_visit_reminders (
 id TEXT PRIMARY KEY, appointment_id TEXT NOT NULL REFERENCES bm_appointments(id),
 start_at TEXT NOT NULL, lead_minutes INTEGER NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('email','sms')),
 due_at TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sending','sent','failed','cancelled','uncertain')),
 attempted_at TEXT, sent_at TEXT, outcome TEXT,
 UNIQUE(appointment_id,start_at,lead_minutes,channel)
);
CREATE TABLE bm_visit_reply_links (
reminder_id TEXT PRIMARY KEY REFERENCES bm_visit_reminders(id), token_hash TEXT NOT NULL UNIQUE, revoked_at TEXT
);
CREATE INDEX bm_visit_reminders_due ON bm_visit_reminders(state,due_at);
CREATE TRIGGER bm_visit_reminders_changed AFTER UPDATE OF start_at,status ON bm_appointments
 WHEN NEW.start_at<>OLD.start_at OR NEW.status<>'booked' BEGIN
 UPDATE bm_visit_reminders SET state='cancelled' WHERE appointment_id=NEW.id AND state IN ('pending','sending','failed');
 UPDATE bm_visit_reply_links SET revoked_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE reminder_id IN (SELECT id FROM bm_visit_reminders WHERE appointment_id=NEW.id);
 UPDATE bm_appointments SET patient_response='awaiting',patient_response_at=NULL WHERE id=NEW.id AND NEW.start_at<>OLD.start_at;
END;

CREATE TRIGGER bm_message_email_changed AFTER UPDATE OF email ON bm_clients
 WHEN NEW.email IS NOT OLD.email BEGIN
 UPDATE bm_message_links SET revoked_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE client_id=NEW.id AND revoked_at IS NULL;
 END;

-- Insurance records contain PHI. Reads use the same live-role and audit fences
-- as the patient file. X12 exports remain available without provider egress.
CREATE TABLE bm_insurance_settings (
 id INTEGER PRIMARY KEY CHECK(id=1), billing_npi TEXT NOT NULL, tax_id TEXT NOT NULL,
 address TEXT NOT NULL, city TEXT NOT NULL, state TEXT NOT NULL, postal_code TEXT NOT NULL,
 sender_id TEXT NOT NULL, contact_name TEXT NOT NULL, contact_phone TEXT NOT NULL,
 production INTEGER NOT NULL DEFAULT 0 CHECK(production IN (0,1)), version INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE bm_payers (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, payer_id TEXT NOT NULL UNIQUE, receiver_id TEXT NOT NULL,
 medicare INTEGER NOT NULL DEFAULT 0 CHECK(medicare IN (0,1)),
 unit_method TEXT CHECK(unit_method IN ('cms','ama')), requires_referral INTEGER NOT NULL DEFAULT 0 CHECK(requires_referral IN (0,1)),
 version INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE bm_payer_fees (
 payer_id TEXT NOT NULL REFERENCES bm_payers(id), code TEXT NOT NULL,
 cents INTEGER NOT NULL CHECK(cents>0), PRIMARY KEY(payer_id,code)
);
CREATE TABLE bm_payer_enrollments (
 payer_id TEXT NOT NULL REFERENCES bm_payers(id), practitioner_id TEXT NOT NULL REFERENCES bm_staff(id),
 taxonomy TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), PRIMARY KEY(payer_id,practitioner_id)
);
CREATE TABLE bm_policies (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id), payer_id TEXT NOT NULL REFERENCES bm_payers(id),
 member_id TEXT NOT NULL, group_number TEXT NOT NULL DEFAULT '', plan_name TEXT NOT NULL DEFAULT '',
 relationship TEXT NOT NULL CHECK(relationship IN ('18','01','19')),
 subscriber_first TEXT NOT NULL, subscriber_last TEXT NOT NULL, subscriber_dob TEXT NOT NULL, subscriber_sex TEXT NOT NULL CHECK(subscriber_sex IN ('M','F','U')),
 patient_sex TEXT NOT NULL CHECK(patient_sex IN ('M','F','U')), address TEXT NOT NULL, city TEXT NOT NULL, state TEXT NOT NULL, postal_code TEXT NOT NULL,
 starts_on TEXT NOT NULL, ends_on TEXT, priority INTEGER NOT NULL DEFAULT 1 CHECK(priority BETWEEN 1 AND 3),
 eligibility_status TEXT NOT NULL DEFAULT 'unknown', eligibility_checked_at TEXT, copay_cents INTEGER, deductible_cents INTEGER,
 version INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX bm_policies_client ON bm_policies(client_id,priority);
CREATE TABLE bm_authorizations (
 id TEXT PRIMARY KEY, policy_id TEXT NOT NULL REFERENCES bm_policies(id), number TEXT NOT NULL,
 starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, visits INTEGER NOT NULL CHECK(visits>0),
 practitioner_id TEXT REFERENCES bm_staff(id), booking_action TEXT NOT NULL CHECK(booking_action IN ('warn','block')),
 version INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE bm_eligibility (
 id TEXT PRIMARY KEY, policy_id TEXT NOT NULL REFERENCES bm_policies(id), service_date TEXT NOT NULL,
 trace TEXT NOT NULL UNIQUE, request TEXT NOT NULL, response TEXT, response_sha256 TEXT UNIQUE,
 benefits TEXT CHECK(benefits IS NULL OR json_valid(benefits)), status TEXT NOT NULL DEFAULT 'prepared',
 created_at TEXT NOT NULL, checked_at TEXT, version INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE bm_medicare_years (
 client_id TEXT NOT NULL REFERENCES bm_clients(id), year INTEGER NOT NULL, therapy_group TEXT NOT NULL CHECK(therapy_group IN ('pt_slp','ot')),
 threshold_cents INTEGER NOT NULL CHECK(threshold_cents>0), external_used_cents INTEGER NOT NULL DEFAULT 0 CHECK(external_used_cents>=0),
 source TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(client_id,year,therapy_group)
);
CREATE TABLE bm_claims (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id), appointment_id TEXT NOT NULL REFERENCES bm_appointments(id),
 policy_id TEXT NOT NULL REFERENCES bm_policies(id), invoice_id TEXT NOT NULL REFERENCES bm_invoices(id),
 replaces_id TEXT REFERENCES bm_claims(id), payer_control TEXT NOT NULL DEFAULT '',
 snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), errors TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(errors)),
 status TEXT NOT NULL CHECK(status IN ('draft','ready','batched','exported','submitted','accepted','rejected','paid','partial','denied','corrected')),
 amount_cents INTEGER NOT NULL CHECK(amount_cents>0), therapy_group TEXT NOT NULL CHECK(therapy_group IN ('pt_slp','ot')),
 service_date TEXT NOT NULL, medical_necessity TEXT NOT NULL DEFAULT '', appeal TEXT NOT NULL DEFAULT '',
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX bm_claim_live_visit ON bm_claims(appointment_id,policy_id) WHERE status<>'corrected';
CREATE INDEX bm_claims_client ON bm_claims(client_id,service_date);
CREATE TABLE bm_claim_batches (
 id TEXT PRIMARY KEY, payer_id TEXT NOT NULL REFERENCES bm_payers(id), body TEXT NOT NULL, sha256 TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('prepared','exported','sending','submitted','uncertain')), reference TEXT,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE bm_claim_batch_items (
 batch_id TEXT NOT NULL REFERENCES bm_claim_batches(id), claim_id TEXT NOT NULL UNIQUE REFERENCES bm_claims(id), PRIMARY KEY(batch_id,claim_id)
);
CREATE TABLE bm_insurance_imports (
 id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('277CA','835')), sha256 TEXT NOT NULL UNIQUE,
 trace TEXT NOT NULL, payer_id TEXT NOT NULL REFERENCES bm_payers(id), amount_cents INTEGER,
 imported_by TEXT NOT NULL, imported_at TEXT NOT NULL, UNIQUE(kind,payer_id,trace)
);
