 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id),
 title TEXT NOT NULL, document_type TEXT NOT NULL CHECK(document_type IN ('referral','imaging','order','signed_plan','photo','other')),
 document_date TEXT NOT NULL, search_text TEXT NOT NULL DEFAULT '',
 filename TEXT NOT NULL, mime TEXT NOT NULL CHECK(mime IN ('image/jpeg','image/png','image/webp','application/pdf')),
 byte_length INTEGER NOT NULL CHECK(byte_length BETWEEN 1 AND 1000000),
 content_base64 TEXT NOT NULL, sha256 TEXT NOT NULL,
 created_at TEXT NOT NULL, created_by TEXT NOT NULL
);
CREATE INDEX bm_chart_document_patient ON bm_chart_documents(client_id,document_date,id);
CREATE TRIGGER bm_chart_document_fixed BEFORE UPDATE ON bm_chart_documents BEGIN SELECT RAISE(ABORT,'chart_document_fixed'); END;
CREATE TRIGGER bm_chart_document_kept BEFORE DELETE ON bm_chart_documents BEGIN SELECT RAISE(ABORT,'documents_are_health_records'); END;

-- Durable application association exists before sending; messages and clinical text are not stored here.
CREATE TABLE bm_mail_attempts (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id),
 kind TEXT NOT NULL CHECK(kind IN ('booking','intake','moved','cancelled','reminder')),
 provider TEXT NOT NULL, tenant_id TEXT NOT NULL, event_namespace TEXT NOT NULL,
 recipient TEXT NOT NULL, provider_message_id TEXT,
 submission_state TEXT NOT NULL CHECK(submission_state IN ('sending','accepted','failed','uncertain','suppressed','no_email','unavailable')),
 created_at TEXT NOT NULL, completed_at TEXT
);
CREATE INDEX bm_mail_attempts_client ON bm_mail_attempts(client_id,created_at);
CREATE INDEX bm_mail_attempts_provider ON bm_mail_attempts(provider,tenant_id,event_namespace,provider_message_id,recipient);
CREATE TABLE bm_mail_attempt_visits (
 delivery_id TEXT NOT NULL REFERENCES bm_mail_attempts(id), appointment_id TEXT NOT NULL REFERENCES bm_appointments(id),
 PRIMARY KEY(delivery_id,appointment_id)
);
CREATE TABLE bm_mail_reply_links (
 token_hash TEXT PRIMARY KEY, appointment_id TEXT NOT NULL REFERENCES bm_appointments(id), start_at TEXT NOT NULL
);
-- Additive migration. Never drop existing delivery receipts or state.
CREATE TABLE IF NOT EXISTS rer_mail_event_receipts (
  provider TEXT NOT NULL,
  tenant_id TEXT NOT NULL,
  event_namespace TEXT NOT NULL,
  event_id TEXT NOT NULL,
  fingerprint TEXT NOT NULL,
  event_json TEXT NOT NULL,
  commit_token TEXT NOT NULL,
  ordinal INTEGER NOT NULL,
  conflict INTEGER NOT NULL DEFAULT 0 CONSTRAINT rer_mail_event_identity_conflict CHECK (conflict = 0),
  PRIMARY KEY (provider, tenant_id, event_namespace, event_id)
);
CREATE TABLE IF NOT EXISTS rer_mail_event_states (
  provider TEXT NOT NULL,
  tenant_id TEXT NOT NULL,
  event_namespace TEXT NOT NULL,
  provider_message_id TEXT NOT NULL,
  recipient TEXT NOT NULL,
  status TEXT NOT NULL,
  occurred_at INTEGER NOT NULL,
  event_id TEXT NOT NULL,
  terminal INTEGER NOT NULL CHECK (terminal IN (0, 1)),
  PRIMARY KEY (provider, tenant_id, event_namespace, provider_message_id, recipient)
);
-- Reply credentials are invalid after a change even when only the clinician or room changes.
CREATE TRIGGER bm_mail_links_changed AFTER UPDATE OF start_at,status,practitioner_id,room_id ON bm_appointments
 WHEN NEW.start_at<>OLD.start_at OR NEW.status<>OLD.status OR NEW.practitioner_id<>OLD.practitioner_id OR NEW.room_id IS NOT OLD.room_id BEGIN
 DELETE FROM bm_mail_reply_links WHERE appointment_id=NEW.id;
 UPDATE bm_visit_reply_links SET revoked_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE reminder_id IN (SELECT id FROM bm_visit_reminders WHERE appointment_id=NEW.id);
END;

-- CHART-013: owner-granted read-only care-team access to one patient's notes,
-- and audited 12-hour break-glass openings with the owner's in-app notice.
CREATE TABLE bm_care_grants (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id), practitioner_id TEXT NOT NULL REFERENCES bm_staff(id),
 granted_by TEXT NOT NULL, granted_at TEXT NOT NULL, revoked_by TEXT, revoked_at TEXT
);
CREATE UNIQUE INDEX bm_care_grants_live ON bm_care_grants(client_id,practitioner_id) WHERE revoked_at IS NULL;
CREATE TRIGGER bm_care_grants_revoke_only BEFORE UPDATE ON bm_care_grants
 WHEN OLD.revoked_at IS NOT NULL OR NEW.id IS NOT OLD.id OR NEW.client_id IS NOT OLD.client_id OR NEW.practitioner_id IS NOT OLD.practitioner_id
  OR NEW.granted_by IS NOT OLD.granted_by OR NEW.granted_at IS NOT OLD.granted_at
 BEGIN SELECT RAISE(ABORT,'care_grant_fixed'); END;
CREATE TRIGGER bm_care_grants_no_delete BEFORE DELETE ON bm_care_grants BEGIN SELECT RAISE(ABORT,'care_grant_fixed'); END;

CREATE TABLE bm_break_glass (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id), practitioner_id TEXT NOT NULL REFERENCES bm_staff(id),
 opened_by TEXT NOT NULL, reason TEXT NOT NULL, opened_at TEXT NOT NULL, expires_at TEXT NOT NULL,
 ended_by TEXT, ended_at TEXT, acknowledged_by TEXT, acknowledged_at TEXT
);
CREATE INDEX bm_break_glass_open ON bm_break_glass(client_id,practitioner_id,expires_at);
CREATE TRIGGER bm_break_glass_fixed BEFORE UPDATE ON bm_break_glass
 WHEN NEW.id IS NOT OLD.id OR NEW.client_id IS NOT OLD.client_id OR NEW.practitioner_id IS NOT OLD.practitioner_id OR NEW.opened_by IS NOT OLD.opened_by
  OR NEW.reason IS NOT OLD.reason OR NEW.opened_at IS NOT OLD.opened_at OR NEW.expires_at IS NOT OLD.expires_at
  OR (OLD.ended_at IS NOT NULL AND NEW.ended_at IS NOT OLD.ended_at) OR (OLD.acknowledged_at IS NOT NULL AND NEW.acknowledged_at IS NOT OLD.acknowledged_at)
 BEGIN SELECT RAISE(ABORT,'break_glass_fixed'); END;
CREATE TRIGGER bm_break_glass_no_delete BEFORE DELETE ON bm_break_glass BEGIN SELECT RAISE(ABORT,'break_glass_fixed'); END;

CREATE TABLE bm_followup_settings (
