);
CREATE INDEX bm_plan_installments_due ON bm_plan_installments(status,due_on);
CREATE TABLE bm_balance_reminders (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES bm_clients(id),
