 SELECT 1 FROM bm_note_submissions s WHERE s.note_id=NEW.note_id AND NOT EXISTS(SELECT 1 FROM bm_note_reviews r WHERE r.submission_id=s.id)
) BEGIN SELECT RAISE(ABORT,'note_locked'); END;
